async function listR2Buckets(accountId) {
  const results = await fetchResult(`/accounts/${accountId}/r2/buckets`);
  return results.buckets;
}
async function createR2Bucket(accountId, bucketName) {
  return await fetchResult(`/accounts/${accountId}/r2/buckets`, {
    method: "POST",
    body: JSON.stringify({ name: bucketName })
  });
}
